<script setup>
import PRViewer from '@/components/repo/PRViewer.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col overflow-hidden bg-base-100">
    <!-- No project: nothing to inspect -->
    <div v-if="!project" class="flex flex-col items-center justify-center gap-2 grow text-base-content/40">
      <i class="fa-solid fa-code-branch text-3xl"></i>
      <span class="text-sm">No active project</span>
    </div>

    <template v-else>
      <!-- Toolbar: project, branch comparison and a manual refresh -->
      <header class="flex items-center gap-2 flex-wrap px-3 py-2 bg-base-200 border-b border-base-content/10 shrink-0">
        <i class="fa-solid fa-code-branch text-warning shrink-0"></i>
        <span class="text-sm font-semibold truncate">{{ project.project_name }}</span>

        <div class="flex items-center gap-1 ml-auto text-xs">
          <label class="sr-only" for="git-view-compare-branch">Compare against</label>
          <select
            id="git-view-compare-branch"
            class="select select-xs select-bordered max-w-40"
            v-model="compareBranch"
            :disabled="loading"
            @change="loadChanges"
          >
            <option value="local">local changes</option>
            <option v-for="branch in branches" :key="'compare-' + branch" :value="branch">{{ branch }}</option>
          </select>

          <i class="fa-solid fa-arrow-right text-base-content/40"></i>

          <label class="sr-only" for="git-view-branch">Branch</label>
          <select
            id="git-view-branch"
            class="select select-xs select-bordered max-w-40"
            v-model="currentBranch"
            :disabled="loading"
            @change="loadChanges"
          >
            <option v-for="branch in branches" :key="'branch-' + branch" :value="branch">{{ branch }}</option>
          </select>

          <button class="btn btn-xs btn-ghost" :disabled="loading" title="Reload repository" @click="loadChanges">
            <i class="fa-solid fa-rotate-right" :class="{ 'animate-spin': loading }"></i>
          </button>
        </div>
      </header>

      <!-- Empty state: no git repository, or nothing to compare -->
      <div
        v-if="!loading && !hasChanges"
        class="flex flex-col items-center justify-center gap-2 grow text-base-content/40"
      >
        <i class="fa-regular fa-folder-open text-3xl"></i>
        <span class="text-sm">
          {{ branches.length ? 'No changes between the selected branches' : 'No git repository in this project' }}
        </span>
      </div>

      <!-- Diff view (file list + diff), reused from the PR viewer -->
      <PRViewer
        v-else
        class="grow min-h-0"
        :project="project"
        :from-branch="currentBranch"
        :to-branch="compareBranch"
        :available-branches="branches"
        :repo-changes="repoChanges"
        :loading="loading"
        @refresh="loadChanges"
      />
    </template>
  </div>
</template>

<script>
// Project-level Git screen. Opened by the sidebar "Git" item
// (config/apps.js → git-view) as a dockview panel on desktop and as the
// "/:projectName/git-view" route in single / mobile mode.
//
// It only needs the regular repo endpoints (API.repo.branches / API.repo.changes)
// and reuses PRViewer to render the diff, so the change list, the file tree and
// the split/unified toggles behave exactly like the ones in the PR review.
export default {
  name: 'GitView',
  props: {
    // Panel / route params (unused today, kept so AppRouteView and dockview
    // can pass them without Vue warning about extraneous attributes).
    params: { type: Object, default: () => ({}) }
  },
  data() {
    return {
      branches: [],
      currentBranch: '',
      compareBranch: 'local',
      repoChanges: null,
      loading: false
    }
  },
  computed: {
    project() {
      return this.$storex.projects.activeProject || null
    },
    // Whether the last comparison returned any changed file
    hasChanges() {
      const changed = this.repoChanges?.branch_file_and_commits
      return !!changed && Object.keys(changed).length > 0
    }
  },
  watch: {
    // Switching the active project loads the repository of the new one
    'project.project_id'() {
      this.loadRepository()
    }
  },
  created() {
    this.loadRepository()
  },
  methods: {
    // Branches first: the diff request needs two valid branch names
    async loadRepository() {
      if (!this.project) return
      this.loading = true
      try {
        const branches = await this.$storex.api.repo.branches()
        this.branches = Array.isArray(branches) ? branches : (branches?.branches || [])
        if (!this.branches.includes(this.currentBranch)) {
          this.currentBranch = this.branches[0] || 'main'
        }
        await this.loadChanges()
      } catch (ex) {
        console.error('Error loading repository', ex)
        this.repoChanges = null
        this.branches = []
      } finally {
        this.loading = false
      }
    },
    async loadChanges() {
      if (!this.project) return
      this.loading = true
      try {
        this.repoChanges = await this.$storex.api.repo.changes({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch
        })
      } catch (ex) {
        console.error('Error loading changes', ex)
        this.repoChanges = null
      } finally {
        this.loading = false
      }
    }
  }
}
</script>
</file_change>

